import re
p='configs/pyrightconfig.json'
s=open(p).read()
s=re.sub(r'  // Decision for #325.*?\n(  "reportUnknownMemberType": )"none"',r'  // #325: strict repo-wide; app/ is carved out in the root pyrightconfig.json (Reflex stub noise).\n\1"error"',s,flags=re.S)
open(p,'w').write(s)
open('pyrightconfig.json','w').write('''{
  "extends": "./configs/pyrightconfig.json",
  "venvPath": ".",
  "venv": ".venv",
  // #325: reportUnknownMemberType is "error" everywhere except app/. ~95% of findings there come
  // from Reflex's partially-unknown element/chart stubs (rx.el.div, p, span, .render, ...), which
  // are not fixable in this repo. app/ is still type-checked for every other rule.
  // Environments match first-wins, so the catch-all "." must stay last.
  "executionEnvironments": [
    { "root": "app", "reportUnknownMemberType": "none" },
    { "root": "." }
  ]
}
''')
